gcc -o rngs rngs.c && python3 - <<'EOF'
import subprocess
obs='TTTTTTTTATTAAAATATTTAAAAATAATAATAATTTTAAATATAATTATATATATAATA'+'AATATTTTAATAAAAAAATTTTAAAATATTTTATTTATTA'
picks=[1 if c=='A' else 0 for c in obs]  # 1=A 0=T
for mode in range(7):
    out=subprocess.run(['./rngs',str(mode)],capture_output=True,text=True).stdout.split()
    s=[float(x) for x in out]
    for cpp in (1,2,3):
        for which in range(cpp):
            vals=[s[i*cpp+which] for i in range(100)]
            for d in (0,1):
                pred=[1 if (v<0.5) else 0 for v in vals] if d==0 else [1 if (v>=0.5) else 0 for v in vals]
                m=sum(1 for a,b in zip(pred,picks) if a==b)
                if m>60: print('mode',mode,'cpp',cpp,'which',which,'dir',d,'match',m)
print('done')
